// Define the required function signature (Callback)
typedef int (*OpHandler)(int a, int b);

// Concrete implementation 1
int op_add(int a, int b) { return a + b; }

// Concrete implementation 2
int op_mult(int a, int b) { return a * b; }

// Core function that uses the callback
int execute_op(OpHandler handler, int x, int y) {
    return handler(x, y);
}

// Usage (Assigning and passing directly)
OpHandler current_op = op_mult;
int result1 = execute_op(op_add, 10, 5);
int result2 = execute_op(current_op, 10, 5);
// result1 == 15
// result2 == 50
// Pointer comparison: current_op == &op_mult
